            ruta.write_text("hola hola\nchau\n", encoding="utf-8")
            codigo, salida, _ = correr("contar", str(ruta), "--json")
            self.assertEqual(codigo, 0)
            self.assertEqual(json.loads(salida)["palabras"], 3)

