# ======================================================================
# MÓDULO: recetas
# ======================================================================
"""
Recetario: fragmentos de código correctos y probados para tareas frecuentes.

Para un modelo de 24B, un buen ejemplo en el contexto vale más que mil
instrucciones. Cuando el pedido coincide claramente con una receta (por sus
etiquetas), REAPER agrega 1-2 recetas al prompt del implementador. También se
consultan a mano con /recetas <tema>.
"""


@dataclass(frozen=True)
class Receta:
    titulo: str
    lenguaje: str
    etiquetas: tuple
    descripcion: str
    codigo: str


RECETAS: list[Receta] = []


def receta(titulo: str, lenguaje: str, etiquetas: str, descripcion: str, codigo: str) -> Receta:
    r = Receta(titulo, lenguaje, tuple(e.strip() for e in etiquetas.split(",") if e.strip()),
               descripcion.strip(), textwrap.dedent(codigo).strip("\n"))
    RECETAS.append(r)
    return r


def _tokens_receta(r: Receta) -> tuple[set, set, set]:
    etiquetas = {_raiz(sin_tildes(e.lower())) for e in r.etiquetas for e in e.split()}
    titulo = {_raiz(sin_tildes(t)) for t in re.findall(r"[a-záéíóúñ0-9]{3,}", r.titulo.lower())}
    descripcion = {_raiz(sin_tildes(t)) for t in re.findall(r"[a-záéíóúñ0-9]{4,}", r.descripcion.lower())}
    return etiquetas, titulo, descripcion


def puntuar_receta(r: Receta, tokens: dict, con_distintos: bool = False):
    etiquetas, titulo, descripcion = _tokens_receta(r)
    puntaje = 0.0
    distintos = 0
    for t, peso in tokens.items():
        acierto = False
        if t in etiquetas:
            puntaje += 3 * peso
            acierto = True
        if t in titulo:
            puntaje += 2 * peso
            acierto = True
        if t in descripcion:
            puntaje += 0.5 * peso
        distintos += acierto
    return (puntaje, distintos) if con_distintos else puntaje


def buscar_recetas(consulta: str, k: int = 4, lenguaje: str = "") -> list[Receta]:
    tokens = tokens_pedido(consulta)
    if not tokens:
        return []
    puntuadas = []
    for i, r in enumerate(RECETAS):
        if lenguaje and r.lenguaje != lenguaje:
            continue
        p = puntuar_receta(r, tokens)
        if p > 0:
            puntuadas.append((p, -i, r))
    puntuadas.sort(key=lambda t: (-t[0], -t[1]))
    return [r for _, _, r in puntuadas[:k]]


_PALABRAS_LENGUAJE = {
    "go": (" go ", "golang", "go.mod"), "rust": ("rust", "cargo"), "c": (" en c ", " c99", "makefile", " c "),
    "java": ("java ", "java.", " java"), "php": (" php", "php "), "ruby": ("ruby",), "perl": ("perl",),
    "javascript": ("javascript", "node", " js ", "web", "html", "navegador", "react"),
    "bash": ("bash", "shell", " sh ", "script de terminal"), "python": ("python", " py "),
}
_EXT_LENGUAJE = {".py": "python", ".go": "go", ".rs": "rust", ".c": "c", ".h": "c", ".java": "java", ".php": "php",
                 ".rb": "ruby", ".pl": "perl", ".pm": "perl", ".sh": "bash", ".js": "javascript", ".mjs": "javascript",
                 ".ts": "javascript", ".html": "javascript"}


def lenguajes_mencionados(texto: str, archivos: Iterable[str] = ()) -> set:
    """Lenguajes que el pedido nombra (o que usan los archivos indicados)."""
    t = f" {(texto or '').lower()} "
    salida = {lang for lang, palabras in _PALABRAS_LENGUAJE.items() if any(p in t for p in palabras)}
    salida |= {_EXT_LENGUAJE[Path(a).suffix.lower()] for a in archivos if Path(a).suffix.lower() in _EXT_LENGUAJE}
    return salida


def recetas_para_prompt(tarea: str, k: int = 2, umbral: float = 5.0, maximo: int = 2600,
                        lenguajes: Optional[Iterable[str]] = None) -> str:
    """Recetas que coinciden FUERTE con la tarea (si no, nada: mejor sin ruido) y en un lenguaje que sirva."""
    tokens = tokens_pedido(tarea)
    if not tokens:
        return ""
    permitidos = set(lenguajes) if lenguajes is not None else lenguajes_mencionados(tarea)
    if not permitidos:
        permitidos = {"python", "bash", "javascript"}   # lo habitual en Termux si no se dice otra cosa
    permitidos.add("bash")
    if "javascript" in permitidos:
        permitidos |= {"html", "css"}
    candidatas = [r for r in RECETAS if r.lenguaje in permitidos]
    puntuadas = sorted(((*puntuar_receta(r, tokens, con_distintos=True), r) for r in candidatas), key=lambda t: -t[0])
    # Hace falta una coincidencia fuerte: puntaje alto Y al menos dos palabras distintas del pedido.
    elegidas = [r for p, distintos, r in puntuadas[:k] if p >= umbral and distintos >= 2]
    if not elegidas:
        return ""
    partes, usado = [], 0
    for r in elegidas:
        bloque = f"### {r.titulo} ({r.lenguaje})\n{r.descripcion}\n```{r.lenguaje}\n{r.codigo}\n```"
        if usado + len(bloque) > maximo:
            break
        partes.append(bloque)
        usado += len(bloque)
    return "RECETAS DE REFERENCIA (código probado; adaptalo, no lo copies a ciegas):\n" + "\n\n".join(partes) if partes else ""


