    def test_afirmacion_tras_ejecucion_bloqueada_se_rechaza(self):
        """El caso real: dijo 'validé' cuando la ejecución había sido rechazada como repetida."""
        ws = self.proyecto({"roto.py": "raise SystemExit(1)\n"})
