# ======================================================================
# MÓDULO: evidence
# ======================================================================
"""
Evidence Core (v9, Fase 2): separar CLAIM (lo que un agente afirma) de EVIDENCE (lo que una herramienta
observó), y un EvidenceGate que decide el NIVEL de verificación en vez de aceptar "funciona" a secas.

Ataca los fallos de v8:
  §1.4 "todos los tests pasan, por lo tanto no hay errores"  → CLAIM_SCOPE_EXCEEDS_EVIDENCE
  §1.1/1.2 tests verdes pero tautológicos o que mockean el sistema → TEST_SUITE_GREEN ≠ BEHAVIOR_VERIFIED
  §31 evidencia de una revisión vieja → STALE_EVIDENCE

La filosofía: los modelos proponen, las herramientas observan, la evidencia decide.
"""

# Niveles de verificación, de menor a mayor fuerza (MASTER SPEC §1.4).
NIVELES_VERIFICACION = ("UNVERIFIED", "TEST_SUITE_GREEN", "PARTIALLY_VERIFIED", "BEHAVIOR_VERIFIED",
                        "INTEGRATION_VERIFIED", "SPEC_VERIFIED")
# Estados de un claim.
ESTADOS_CLAIM = ("UNVERIFIED", "SUPPORTED", "PARTIALLY_SUPPORTED", "CONTRADICTED", "REJECTED", "STALE")


@dataclass
class ToolReceipt:
    """Observación cruda de una herramienta (lo único en lo que el gate confía)."""
    source: str                       # run_tests | validate | execute_command | run_python | inspect_tests
    exit_code: Optional[int] = None
    ok: bool = False
    resumen: str = ""
    revision: str = ""                # huella del workspace cuando se observó
    discriminacion: float = 1.0       # si aplica (tests): 1.0 = discriminan; <1 = débiles
    timestamp: float = field(default_factory=time.time)

    def como_dict(self) -> dict:
        return {"source": self.source, "exit_code": self.exit_code, "ok": self.ok,
                "resumen": recortar(self.resumen, 400), "revision": self.revision,
                "discriminacion": self.discriminacion}


@dataclass
class Claim:
    statement: str
    agent: str = ""
    tipo: str = "resultado"           # resultado | tests | comportamiento | spec
    confidence: float = 0.5
    evidence: list = field(default_factory=list)   # ToolReceipt
    status: str = "UNVERIFIED"
    nivel: str = "UNVERIFIED"
    motivo: str = ""

    def como_dict(self) -> dict:
        return {"statement": recortar(self.statement, 300), "agent": self.agent, "tipo": self.tipo,
                "status": self.status, "nivel": self.nivel, "motivo": self.motivo,
                "evidence": [e.como_dict() for e in self.evidence]}


# Afirmaciones que EXCEDEN lo que un test verde puede demostrar (§1.4).
_RE_EXCEDE = re.compile(
    r"\b(no\s+(?:hay|tiene|existen?|quedan)\s+(?:errores|bugs?|fallos?|problemas?)"
    r"|sin\s+(?:errores|bugs?|fallos?)\b"
    r"|(?:100|cien)\s*%?\s*(?:correcto|funcional|cubierto)"
    r"|funciona\s+(?:perfectamente|a\s+la\s+perfecci[óo]n)"
    r"|listo\s+para\s+producci[óo]n|production[- ]ready"
    r"|totalmente\s+(?:correcto|verificad|probad)|completamente\s+(?:correcto|verificad|probad)"
    r"|garantiz\w+\s+que|imposible\s+que\s+falle|no\s+puede\s+fallar"
    r"|bug[- ]free|no\s+bugs?\b)",
    re.I,
)
# Afirmaciones de que los tests pasan.
_RE_TESTS_PASAN = re.compile(
    r"\b(?:todos\s+los\s+)?tests?\s+(?:pasan|pasaron|est[áa]n\s+en\s+verde|ok)\b"
    r"|\b(?:all\s+)?tests?\s+pass(?:ed)?\b|\b\d+\s*/\s*\d+\b|pytest\b.*\bok\b|unittest.*\bok\b",
    re.I,
)
# Afirmaciones de comportamiento ("funciona", "anda", "corre bien").
_RE_COMPORTAMIENTO = re.compile(
    r"\b(funciona|anda|corre|ejecuta)\b(?!\s+(?:de|como))|se\s+comporta|produce\s+(?:el|la)\s+(?:resultado|salida)"
    r"\s+(?:correct|esperad)|verifiqu[ée]\s+el\s+comportamiento",
    re.I,
)


def _revision(ws) -> str:
    try:
        return ws.huella()
    except (OSError, AttributeError):
        return ""


def receipt_de_evidencia(tipo: str, estado: str, ws=None, resumen: str = "",
                         discriminacion: float = 1.0) -> ToolReceipt:
    """Construye un ToolReceipt a partir de la evidencia que el agente ya registra (tipo, estado)."""
    ok = estado == "ok"
    return ToolReceipt(source=tipo, ok=ok, exit_code=0 if ok else 1, resumen=resumen,
                       revision=_revision(ws) if ws is not None else "", discriminacion=discriminacion)


def discriminacion_de_tests(ws, limite: int = 60) -> tuple[float, list[str]]:
    """
    Discriminación media de los tests Python del proyecto y los problemas ALTA (tautología, mock del sujeto).
    1.0 y [] si no hay tests Python o están sanos.
    """
    try:
        archivos = [ws.rel(p) for p in ws.iterar(limite=limite * 3)
                    if ws.rel(p).endswith(".py") and es_archivo_de_test(ws.rel(p))][:limite]
    except OSError:
        return 1.0, []
    if not archivos:
        return 1.0, []
    valores, problemas = [], []
    for rel in archivos:
        try:
            res = analizar_tests_python(ws.leer(rel))
        except (OSError, ValueError, ErrorRuta):
            continue
        valores.append(res.discriminacion)
        for p in res.problemas:
            if p.severidad == "alta" and p.tipo in ("TAUTOLOGIA", "MOCK_SISTEMA_BAJO_PRUEBA", "VALOR_DESDE_MOCK",
                                                    "INTEGRACION_MOCKEADA"):
                problemas.append(f"{rel}: {p.test} [{p.tipo}]")
    if not valores:
        return 1.0, []
    return round(sum(valores) / len(valores), 2), problemas[:12]


class EvidenceGate:
    """
    Evalúa un claim contra evidencia real + inteligencia de tests. No decide 'verdadero/falso':
    asigna un NIVEL de verificación y explica qué falta para subir.
    """

    def __init__(self, ws=None):
        self.ws = ws

    def evaluar(self, claim: Claim) -> Claim:
        texto = claim.statement or ""
        afirma_tests = bool(_RE_TESTS_PASAN.search(texto))
        afirma_comportamiento = bool(_RE_COMPORTAMIENTO.search(texto))
        afirma_exceso = bool(_RE_EXCEDE.search(texto))

        receipts = claim.evidence
        tests_ok = [r for r in receipts if r.source == "run_tests" and r.ok]
        tests_fallan = [r for r in receipts if r.source == "run_tests" and not r.ok]
        corridas = [r for r in receipts if r.source in ("execute_command", "run_python") and r.ok]
        bloqueadas = [r for r in receipts if r.source in ("run_tests", "validate", "execute_command", "run_python")
                      and r.exit_code in (None,) and not r.ok]

        # revisión obsoleta: la última evidencia es de otra revisión que la actual
        revision_actual = _revision(self.ws) if self.ws is not None else ""
        if revision_actual and receipts:
            frescas = [r for r in receipts if not r.revision or r.revision == revision_actual]
            if not frescas and tests_ok:
                claim.status, claim.nivel = "STALE", "UNVERIFIED"
                claim.motivo = ("STALE_EVIDENCE: la evidencia es de una revisión anterior; el código cambió después. "
                                "Volvé a correr los tests sobre el estado actual.")
                return claim

        # discriminación de los tests (Fase 1)
        discriminacion = 1.0
        problemas_tests: list[str] = []
        if self.ws is not None and (afirma_tests or afirma_comportamiento):
            discriminacion, problemas_tests = discriminacion_de_tests(self.ws)
            for r in tests_ok:
                r.discriminacion = discriminacion

        # 0) dijo que los tests pasan pero el último run_tests falló (un run fallido ES evidencia de ejecución)
        if afirma_tests and tests_fallan and not tests_ok:
            claim.status, claim.nivel = "CONTRADICTED", "UNVERIFIED"
            claim.motivo = "decís que los tests pasan pero el último run_tests FALLÓ. Contradice la evidencia."
            return claim

        # 1) nada ejecutado pero afirma éxito
        if (afirma_tests or afirma_comportamiento or afirma_exceso) and not (tests_ok or corridas):
            claim.status, claim.nivel = "UNVERIFIED", "UNVERIFIED"
            if bloqueadas:
                claim.motivo = ("las ejecuciones fueron BLOQUEADAS/rechazadas: no hay evidencia real. "
                                "Corré run_tests o execute_command de verdad.")
            else:
                claim.motivo = "no hay evidencia de ejecución (run_tests / execute_command). Ejecutá antes de afirmar."
            return claim

        # nivel base por lo observado
        nivel = "UNVERIFIED"
        if tests_ok:
            nivel = "TEST_SUITE_GREEN"
        if tests_ok and corridas:
            nivel = "BEHAVIOR_VERIFIED"
        elif corridas and not (afirma_tests or tests_ok):
            nivel = "BEHAVIOR_VERIFIED"

        # 3) tests verdes pero no discriminan → no sube a BEHAVIOR_VERIFIED
        if tests_ok and discriminacion < 0.7 and problemas_tests:
            claim.status, claim.nivel = "PARTIALLY_SUPPORTED", "TEST_SUITE_GREEN"
            claim.motivo = ("TEST_SUITE_GREEN pero NO BEHAVIOR_VERIFIED: los tests pasan pero no discriminan "
                            f"(discriminación {discriminacion}). Problemas: " + "; ".join(problemas_tests[:4])
                            + ". Verde no equivale a correcto; corregí los tests o agregá casos que fallen si el "
                            "código se rompe.")
            return claim

        # 4) el alcance del claim excede la evidencia (§1.4)
        if afirma_exceso:
            claim.status, claim.nivel = "PARTIALLY_SUPPORTED", nivel
            cuanto = (f"{len(tests_ok)} corrida(s) de tests" if tests_ok else "la evidencia disponible")
            claim.motivo = ("CLAIM_SCOPE_EXCEEDS_EVIDENCE: afirmás ausencia total de errores / correctitud "
                            f"absoluta, pero {cuanto} solo demuestra que esos casos pasan. Acotá la afirmación a "
                            "lo que la evidencia respalda (p. ej. 'los N tests pasan sobre esta revisión').")
            return claim

        claim.status = "SUPPORTED" if nivel != "UNVERIFIED" else "UNVERIFIED"
        claim.nivel = nivel
        claim.confidence = {"BEHAVIOR_VERIFIED": 0.85, "TEST_SUITE_GREEN": 0.65, "UNVERIFIED": 0.3}.get(nivel, 0.5)
        return claim


class LibroEvidencia:
    """Registro de claims de una tarea (para el informe final y /claims). Opcional en disco."""

    def __init__(self, ws=None):
        self.ws = ws
        self.claims: list[Claim] = []

    def registrar(self, claim: Claim) -> Claim:
        self.claims.append(claim)
        return claim

    def resumen(self) -> str:
        if not self.claims:
            return "Sin claims registrados."
        lineas = []
        for c in self.claims[-12:]:
            lineas.append(f"[{c.status}/{c.nivel}] {recortar(c.statement, 90)}"
                          + (f"  → {recortar(c.motivo, 120)}" if c.motivo else ""))
        return "\n".join(lineas)

    def guardar(self) -> Optional[Path]:
        if self.ws is None or not self.claims:
            return None
        try:
            carpeta = self.ws.raiz / ".reaper" / "evidencia"
            carpeta.mkdir(parents=True, exist_ok=True)
            ruta = carpeta / f"claims_{datetime.now():%Y%m%d_%H%M%S}.json"
            escritura_atomica(ruta, json.dumps([c.como_dict() for c in self.claims], ensure_ascii=False, indent=2))
            return ruta
        except OSError:
            return None


def evaluar_cierre(ws, informe: str, evidencias: list, agente: str = "") -> Claim:
    """
    Construye un Claim desde el informe final + la evidencia que el agente registró (lista de tuplas
    (tipo, estado, version)) y lo pasa por el EvidenceGate. Devuelve el Claim evaluado.
    """
    receipts = []
    for ev in evidencias[-12:]:
        tipo, estado = ev[0], ev[1]
        receipts.append(receipt_de_evidencia(tipo, estado, ws))
    claim = Claim(statement=informe, agent=agente, evidence=receipts)
    return EvidenceGate(ws).evaluar(claim)


# ======================================================================
# MÓDULO: spec
# ======================================================================
"""
Spec Core + Bug Classifier (v9, Fase 3): la ESPECIFICACIÓN manda sobre los tests.

Ataca los fallos de v8 (MASTER SPEC §1.5-§1.6):
  §1.6  un test exige un efecto que el usuario NUNCA pidió (crear denuncia.txt) → requisito_inventado
  §1.5  "el test falla ⇒ el código está mal": no siempre. Puede ser TEST_BUG, PATH_BUG,
        DEPENDENCY_BUG, FIXTURE_BUG, INPUT_MODEL_BUG, FLAKY_TEST o SPEC_GAP → clasificar_bug
  §..   confundir lo OBSERVADO (un <resultado> real) con lo INTERPRETADO (la conclusión del
        modelo) al diagnosticar → separar_observacion

Orden de autoridad: usuario > spec/plan > interfaz/contrato > criterios > docs > tests > suposiciones.
Un test NO es la fuente de la verdad: CODIFICA la spec, no la inventa.
"""

# Orden de autoridad (ante un conflicto, gana el de más arriba) — MASTER SPEC §1.5.
ORDEN_AUTORIDAD = (
    ("usuario", "lo que el usuario pidió explícitamente"),
    ("spec", "la especificación o el plan aprobado (<plan>, objetivo)"),
    ("contrato", "la interfaz/firmas públicas acordadas"),
    ("criterios", "los criterios de aceptación comprobables"),
    ("docs", "la documentación del proyecto (README, docstrings)"),
    ("tests", "los tests existentes"),
    ("suposiciones", "las suposiciones del modelo"),
)

# Categorías de un test en rojo (por qué falla) — MASTER SPEC §1.5.
TIPOS_BUG = ("IMPLEMENTATION_BUG", "TEST_BUG", "SPEC_GAP", "PATH_BUG", "INPUT_MODEL_BUG",
             "FIXTURE_BUG", "DEPENDENCY_BUG", "FLAKY_TEST", "DESCONOCIDO")

# Módulos de la librería estándar (si falta uno de estos NO es DEPENDENCY_BUG: es otra cosa).
_SP_STDLIB = frozenset((
    "os", "sys", "re", "io", "json", "math", "time", "random", "typing", "pathlib", "collections",
    "itertools", "functools", "datetime", "unittest", "subprocess", "shutil", "tempfile", "argparse",
    "logging", "threading", "asyncio", "socket", "sqlite3", "csv", "hashlib", "base64", "struct",
    "textwrap", "string", "copy", "enum", "dataclasses", "abc", "contextlib", "traceback", "glob",
    "inspect", "ast", "decimal", "fractions", "statistics", "unicodedata", "urllib", "http", "email",
    "html", "xml", "pickle", "gzip", "zipfile", "tarfile", "configparser", "platform", "signal",
    "queue", "heapq", "bisect", "operator", "warnings", "weakref", "types", "numbers", "array",
    "secrets", "uuid", "difflib", "pprint", "shlex", "getpass", "selectors", "concurrent",
))


def nota_autoridad() -> str:
    """Nota para el prompt: el orden de autoridad y que los tests no inventan requisitos."""
    cuerpo = " > ".join(n for n, _ in ORDEN_AUTORIDAD)
    return ("ORDEN DE AUTORIDAD (ante un conflicto, gana el de más arriba):\n  " + cuerpo + "\n"
            "Un test NO define el requisito: lo codifica. Si un test EXIGE algo que el usuario/la spec no "
            "pidieron (un archivo, una ruta, un mensaje exacto), el equivocado es el test (requisito "
            "inventado), no el código. Ante un test en rojo, primero decidí QUÉ está mal (código, test, "
            "spec, ruta, dependencia, fixture, entrada o flaky), no asumas que siempre es el código.")


# ============================================================================ requisitos inventados (§1.6)
@dataclass
class RequisitoInventado:
    test: str
    linea: int
    tipo: str            # ARCHIVO_NO_PEDIDO | RUTA_ABSOLUTA
    artefacto: str
    detalle: str


# Funciones cuyo primer argumento literal es un artefacto que el test EXIGE que exista/ya esté producido.
_SP_EXIGEN_EXISTENCIA = {
    "exists", "isfile", "isdir", "is_file", "is_dir", "lexists", "getsize",
}
# Funciones/métodos que CREAN el artefacto (si el propio test lo crea, no es un requisito al código).
_SP_CREAN = {
    "mkdir", "makedirs", "touch", "write_text", "write_bytes", "mkstemp", "mkdtemp",
    "NamedTemporaryFile", "TemporaryFile", "TemporaryDirectory", "symlink", "link",
}
_SP_MODOS_ESCRITURA = ("w", "a", "x", "+")


def _sp_norm(texto: str) -> str:
    """Normaliza para comparar (minúsculas, sin tildes si está disponible sin_tildes)."""
    try:
        base = sin_tildes(texto or "")
    except NameError:
        base = texto or ""
    return base.lower()


def _sp_literal(nodo) -> Optional[str]:
    if isinstance(nodo, ast.Constant) and isinstance(nodo.value, str):
        return nodo.value
    return None


def _sp_nombre_llamada(nodo) -> str:
    """'exists', 'write_text', 'open'... el atributo o nombre final de una llamada."""
    f = nodo.func
    if isinstance(f, ast.Attribute):
        return f.attr
    if isinstance(f, ast.Name):
        return f.id
    return ""


def _sp_literal_receptor(nodo_call) -> Optional[str]:
    """Literal del receptor en 'Path("x").metodo()' / 'open("x").metodo()': el string está en la llamada base."""
    f = nodo_call.func
    if isinstance(f, ast.Attribute) and isinstance(f.value, ast.Call) and f.value.args:
        return _sp_literal(f.value.args[0])
    return None


def _sp_es_ruta_de_sistema(valor: str) -> bool:
    v = valor.strip()
    if not v:
        return False
    if re.match(r"^[A-Za-z]:[\\/]", v):          # C:\... o C:/...
        return True
    if v.startswith("/") and not re.match(r"^/(tmp|var/folders|private)\b", v):
        return len(v) > 1
    if v.startswith("~"):
        return True
    return False


def requisito_inventado(fuente: str, pedido: str, criterios: str = "") -> list:
    """
    Tests que EXIGEN un artefacto (archivo/ruta) que ni el usuario ni los criterios pidieron, y que el
    propio test tampoco crea. Es el fallo §1.6: el test obliga a producir 'denuncia.txt' por su cuenta.
    Análisis estático; devuelve [] ante SyntaxError o si no hay nada que objetar.
    """
    try:
        arbol = ast.parse(fuente or "")
    except (SyntaxError, ValueError):
        return []
    blob = _sp_norm((pedido or "") + "\n" + (criterios or ""))
    def _base(lit: str) -> str:
        return os.path.basename(lit.rstrip("/\\")) or lit

    def _modo_open(nodo_call) -> str:
        modo = _sp_literal(nodo_call.args[1]) if len(nodo_call.args) >= 2 else ""
        for kw in nodo_call.keywords:
            if kw.arg == "mode":
                modo = _sp_literal(kw.value) or modo
        return modo

    # artefactos que el propio archivo de test crea: no son requisitos al código
    creados: set = set()
    for nodo in ast.walk(arbol):
        if not isinstance(nodo, ast.Call):
            continue
        nombre = _sp_nombre_llamada(nodo)
        if nombre in _SP_CREAN:
            for lit in list(filter(None, [_sp_literal(a) for a in nodo.args] + [_sp_literal_receptor(nodo)])):
                creados.add(_base(lit))
        elif nombre == "open":
            modo = _modo_open(nodo)
            if modo and any(m in modo for m in _SP_MODOS_ESCRITURA):
                lit = _sp_literal(nodo.args[0]) if nodo.args else _sp_literal_receptor(nodo)
                if lit:
                    creados.add(_base(lit))

    def _demandas(nodo_call) -> list:
        nombre = _sp_nombre_llamada(nodo_call)
        salida = []
        if nombre in _SP_EXIGEN_EXISTENCIA or nombre in ("read_text", "read_bytes"):
            salida += [lit for lit in [_sp_literal(a) for a in nodo_call.args] + [_sp_literal_receptor(nodo_call)]
                       if lit]
        elif nombre == "open":
            modo = _modo_open(nodo_call) or "r"
            if not any(m in modo for m in _SP_MODOS_ESCRITURA):
                lit = _sp_literal(nodo_call.args[0]) if nodo_call.args else _sp_literal_receptor(nodo_call)
                if lit:
                    salida.append(lit)
        return salida

    problemas: list = []
    for fn in ast.walk(arbol):
        if not isinstance(fn, ast.FunctionDef) or not fn.name.startswith("test"):
            continue
        for nodo in ast.walk(fn):
            if not isinstance(nodo, ast.Call):
                continue
            for lit in _demandas(nodo):
                base = os.path.basename(lit.rstrip("/\\")) or lit
                if _sp_es_ruta_de_sistema(lit):
                    problemas.append(RequisitoInventado(
                        fn.name, getattr(nodo, "lineno", fn.lineno), "RUTA_ABSOLUTA", lit,
                        f"el test depende de la ruta absoluta '{lit}' del sistema; usá tempfile, no una ruta fija."))
                    continue
                if base in creados:
                    continue
                if _sp_norm(base) in blob or (len(base) > 3 and _sp_norm(os.path.splitext(base)[0]) in blob):
                    continue
                problemas.append(RequisitoInventado(
                    fn.name, getattr(nodo, "lineno", fn.lineno), "ARCHIVO_NO_PEDIDO", base,
                    f"el test exige que exista '{base}', pero ni el usuario ni los criterios lo pidieron y el "
                    f"test no lo crea. Es un requisito inventado: ajustá el test a la spec, no el código a él."))
    # dedup por (test, artefacto, tipo)
    vistos, unicos = set(), []
    for p in problemas:
        clave = (p.test, p.artefacto, p.tipo)
        if clave not in vistos:
            vistos.add(clave)
            unicos.append(p)
    return unicos


def requisitos_inventados_para_prompt(fuente: str, pedido: str, criterios: str = "", maximo: int = 6) -> str:
    problemas = requisito_inventado(fuente, pedido, criterios)
    if not problemas:
        return ""
    lineas = [f"- {p.test} (línea {p.linea}) [{p.tipo}]: {p.detalle}" for p in problemas[:maximo]]
    return ("REQUISITOS INVENTADOS (un test no puede exigir lo que la spec no pide):\n" + "\n".join(lineas))


# ============================================================================ clasificador de bugs (§1.5)
@dataclass
class Clasificacion:
    tipo: str
    confianza: float
    senales: list
    recomendacion: str

    def como_linea(self) -> str:
        return f"{self.tipo} (confianza {self.confianza:.0%}): {self.recomendacion}"


_SP_RECOMENDACION = {
    "DEPENDENCY_BUG": "falta instalar una dependencia de terceros; no la reimplementes a mano: instalala o evitala.",
    "PATH_BUG": "es un problema de ruta/import del propio proyecto (módulo o archivo donde no está). "
                "No cambies la lógica: corregí la ruta, el nombre del módulo o el directorio de trabajo.",
    "IMPLEMENTATION_BUG": "el código produce un resultado o estado incorrecto. Arreglá el código (causa raíz), "
                          "no el test.",
    "TEST_BUG": "el test está mal (valor esperado equivocado, tautología o exige algo que la spec no pide). "
                "Corregí el test contra la spec; NO toques el código para contentar a un test erróneo.",
    "INPUT_MODEL_BUG": "la firma/forma de la entrada no coincide entre el test y la implementación. Alineá la "
                       "interfaz con el contrato acordado antes de tocar la lógica.",
    "FIXTURE_BUG": "falla el armado del test (fixture/setUp), no la lógica bajo prueba. Arreglá el fixture.",
    "FLAKY_TEST": "el test depende de tiempo, azar, red, puertos u orden: es inestable. Hacelo determinista "
                  "(sembrá el azar, mockeá el reloj/red, aislá el estado); no cambies la lógica a ciegas.",
    "SPEC_GAP": "la spec no dice qué se espera acá: el conflicto es de requisitos, no de código. Pedí la "
                "aclaración o decidí según el orden de autoridad, no inventes el comportamiento en el test.",
    "DESCONOCIDO": "no hay una señal clara; recogé más evidencia (el traceback completo) antes de cambiar nada.",
}

_SP_RE_FLAKY = re.compile(
    r"address already in use|connection (?:refused|reset|aborted)|timed?\s*out|\btimeout\b|resource temporarily"
    r"|broken pipe|\bflaky\b|intermittent|randomly|non-?deterministic|\bport\b.*\bin use\b", re.I)
_SP_RE_TIEMPO_AZAR = re.compile(r"\b(datetime\.now|time\.time|random\.|randint|uuid4|monotonic)\b", re.I)


def _sp_modulo_de(error: str) -> str:
    m = re.search(r"No module named ['\"]([\w\.]+)['\"]", error or "")
    return m.group(1).split(".")[0] if m else ""


def clasificar_bug(error: str, *, archivo_test: str = "", codigo_cambiado: bool = True,
                   test_cambiado: bool = False, modulos_proyecto: Iterable[str] = (),
                   requisito_inventado_detectado: bool = False, traceback_txt: str = "") -> Clasificacion:
    """
    Clasifica POR QUÉ falla un test a partir del mensaje de error + contexto. Heurístico y determinista:
    no decide el arreglo, decide dónde mirar (MASTER SPEC §1.5: el test rojo no implica código malo).
    """
    texto = (error or "") + "\n" + (traceback_txt or "")
    proyecto = {m.lower() for m in modulos_proyecto}
    senales: list = []

    def resultado(tipo, confianza, senal):
        senales.append(senal)
        return Clasificacion(tipo, confianza, senales, _SP_RECOMENDACION.get(tipo, _SP_RECOMENDACION["DESCONOCIDO"]))

    # 1) el test exige algo que la spec no pide → el test está mal (puede ser SPEC_GAP si el usuario lo quería)
    if requisito_inventado_detectado:
        return resultado("TEST_BUG", 0.8, "el test exige un artefacto que la spec no pide (requisito inventado)")

    # 2) módulo ausente: dependencia de terceros vs. ruta del propio proyecto
    modulo = _sp_modulo_de(texto)
    if modulo:
        if modulo.lower() in proyecto:
            return resultado("PATH_BUG", 0.85, f"no encuentra el módulo propio '{modulo}' (ruta/paquete mal armado)")
        if modulo.lower() in _SP_STDLIB:
            return resultado("PATH_BUG", 0.6, f"falta un módulo de la stdlib ('{modulo}'): revisá el nombre/entorno")
        return resultado("DEPENDENCY_BUG", 0.85, f"falta la dependencia de terceros '{modulo}'")

    # 3) flaky: red/puertos/tiempo/azar
    if _SP_RE_FLAKY.search(texto):
        return resultado("FLAKY_TEST", 0.8, "error típico de recurso externo/tiempo (red, puerto, timeout)")

    # 4) fixture / setUp
    if re.search(r"fixture ['\"][\w\-]+['\"] not found", texto, re.I):
        return resultado("FIXTURE_BUG", 0.85, "pytest no encuentra un fixture declarado")
    if re.search(r"\bin (?:setUp|setUpClass|setUpModule|tearDown)\b", texto):
        return resultado("FIXTURE_BUG", 0.7, "el error ocurre en el armado/desarme del test, no en la lógica")

    # 5) ruta/archivo ausente
    if re.search(r"FileNotFoundError|No such file or directory", texto, re.I):
        return resultado("PATH_BUG", 0.65, "FileNotFoundError: ruta o directorio de trabajo equivocado, o fixture")

    # 6) firma/forma de la entrada
    if re.search(r"TypeError.*(?:argument|positional|keyword)|missing \d+ required|takes \d+ .*but \d+", texto, re.I):
        return resultado("INPUT_MODEL_BUG", 0.7, "TypeError de argumentos: la firma no coincide con la llamada del test")

    # 7) símbolo inexistente (import name / attribute): implementación incompleta, salvo que el test se tocó solo
    if re.search(r"ImportError: cannot import name|AttributeError:.*has no attribute|NameError: name", texto, re.I):
        if test_cambiado and not codigo_cambiado:
            return resultado("TEST_BUG", 0.55, "el símbolo no existe y lo último que cambió fue el test (quizá un typo)")
        return resultado("IMPLEMENTATION_BUG", 0.65, "falta un símbolo que el contrato promete: implementación incompleta")

    # 8) no implementado
    if re.search(r"NotImplementedError", texto):
        return resultado("IMPLEMENTATION_BUG", 0.8, "NotImplementedError: la implementación está pendiente")

    # 9) assert: valor equivocado. Código vs test según qué se tocó último
    if re.search(r"AssertionError|assert ", texto):
        if test_cambiado and not codigo_cambiado:
            return resultado("TEST_BUG", 0.55, "falla un assert y lo último que cambió fue el test: revisá el esperado")
        return resultado("IMPLEMENTATION_BUG", 0.6, "falla un assert: el código produjo un valor distinto del esperado")

    if _SP_RE_TIEMPO_AZAR.search(texto):
        return resultado("FLAKY_TEST", 0.5, "el test usa tiempo/azar sin fijarlos: posible inestabilidad")

    return resultado("DESCONOCIDO", 0.3, "sin una señal clara en el mensaje de error")


def clasificacion_para_prompt(error: str, **kwargs) -> str:
    c = clasificar_bug(error, **kwargs)
    senales = "; ".join(c.senales[-3:])
    return (f"CLASIFICACIÓN PRELIMINAR DEL FALLO: {c.tipo} (confianza {c.confianza:.0%}).\n"
            f"  Señales: {senales}.\n  {c.recomendacion}\n"
            "  (Es una hipótesis heurística; confirmala con la evidencia antes de arreglar.)")


# ============================================================================ observación vs interpretación
_SP_RE_INTERPRETACION = re.compile(
    r"\b(creo|pienso|supongo|me parece|parece|probablemente|quiz[áa]s?|tal vez|seguramente|deduzco|"
    r"la causa (?:es|ser[íi]a|debe)|el (?:bug|problema|error) est[áa]|por lo tanto|entonces|esto (?:significa|"
    r"implica|quiere decir)|deber[íi]a(?:mos)?|habr[íi]a que|conviene|sospecho|intuyo|asumo|"
    r"i think|i believe|probably|maybe|likely|the (?:cause|bug|problem) is|therefore|this means|should be)\b",
    re.I)
_SP_RE_OBSERVACION = re.compile(
    r"(exit\s*code|exit_code|return code|\bok\b|\bfail(?:ed|ure)?\b|\berror\b|traceback|assert\w*error|"
    r"\bpass(?:ed|aron|a)?\b|\bfall[óa]\w*\b|\d+\s*/\s*\d+|\d+\s+(?:passed|failed|errors?|tests?)|"
    r"stdout|stderr|<resultado|raised|no module named|expected .*but|!=|==)", re.I)


def es_interpretacion(linea: str) -> bool:
    l = (linea or "").strip()
    if not l:
        return False
    return bool(_SP_RE_INTERPRETACION.search(l)) and not _SP_RE_OBSERVACION.search(l)


def es_observacion(linea: str) -> bool:
    l = (linea or "").strip()
    if not l:
        return False
    return bool(_SP_RE_OBSERVACION.search(l)) and not _SP_RE_INTERPRETACION.search(l)


def separar_observacion(texto: str) -> tuple:
    """Separa un diagnóstico en (observaciones, interpretaciones). Una línea que es ambas o ninguna queda fuera."""
    observaciones, interpretaciones = [], []
    for linea in (texto or "").splitlines():
        l = linea.strip(" -•\t")
        if not l:
            continue
        if es_observacion(l):
            observaciones.append(l)
        elif es_interpretacion(l):
            interpretaciones.append(l)
    return observaciones, interpretaciones


def nota_observacion() -> str:
    return ("SEPARÁ OBSERVACIÓN DE INTERPRETACIÓN: una OBSERVACIÓN es lo que viste en un <resultado> real "
            "(salida, exit code, assert). Una INTERPRETACIÓN es tu conclusión sobre la causa. Escribí primero "
            "lo observado y recién después lo interpretado, y nunca presentes una interpretación como un hecho "
            "observado.")


def nota_spec() -> str:
    """Nota combinada (autoridad + observación) para el contexto del reparador/forense."""
    return nota_autoridad() + "\n" + nota_observacion()


# ======================================================================
# MÓDULO: main
# ======================================================================
"""Punto de entrada."""


def construir_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="reaper",
        description=f"REAPER v{__version__} «{__codename__}» · agente de programación autónomo para Termux",
    )
    parser.add_argument("-p", "--pedido", help="ejecuta un pedido con el agente principal y sale")
    parser.add_argument("--construir", help="corre el pipeline completo (tests primero + torneo) y sale")
    parser.add_argument("--plan", help="solo exploración + plan y sale")
    parser.add_argument("--torneo", help="corre un torneo de implementadores para una tarea y sale")
    parser.add_argument("--escribir", nargs=2, metavar=("RUTA", "DESCRIPCION"), help="genera un archivo largo y sale")
    parser.add_argument("--proyecto", help="carpeta del workspace")
    parser.add_argument("--nuevo", nargs=2, metavar=("PLANTILLA", "CARPETA"), help="crea un proyecto desde una plantilla")
    parser.add_argument("--modelo", help="alias o id de OpenRouter (solo esta ejecución)")
    parser.add_argument("--modelo-fuerte", help="modelo para la escalada (solo esta ejecución)")
    parser.add_argument("--perfil", choices=list(PERFILES), help="preset de configuración (solo esta ejecución)")
    parser.add_argument("--modo", choices=MODOS, help="permisos (solo esta ejecución)")
    parser.add_argument("--auto", action="store_true", help="equivale a --modo auto y sin confirmar el plan")
    parser.add_argument("--sin-torneo", action="store_true", help="un solo implementador por tarea")
    parser.add_argument("--sin-animacion", action="store_true", help="banner fijo, sin animar el dragón")
    parser.add_argument("--silencioso", action="store_true", help="muestra menos detalle de los agentes")
    parser.add_argument("--doctor", action="store_true", help="diagnóstico del entorno y sale")
    parser.add_argument("--instalar", action="store_true", help="crea el comando `reaper` y sale")
    parser.add_argument("--autotest", action="store_true", help="corre los tests internos de REAPER (sin API) y sale")
    parser.add_argument("--evaluar", nargs="?", const=0, type=int, metavar="N",
                        help="benchmark con tareas reales (usa la API) y sale")
    parser.add_argument("--comportamiento", nargs="*", metavar="ID",
                        help="evals de comportamiento con el modelo real (5+5, tool loop, interactivos...) y sale")
    parser.add_argument("--dragon", action="store_true", help="muestra el dragón y sale")
    parser.add_argument("--version", action="version", version=f"REAPER {__version__} «{__codename__}»")
    return parser


def main(argv: Optional[list] = None) -> int:
    args = construir_parser().parse_args(argv)

    if args.autotest:
        return correr_autotest()
    if args.dragon:
        if not animar_intro():
            print(banner_dragon())
        return 0

    asegurar_dirs()
    settings = cargar_settings()
    aplicar_tema(settings.tema)
    if args.perfil:
        aplicar_perfil(settings, args.perfil)
    if args.modelo:
        settings.modelo = resolver_modelo(args.modelo)
    if args.modelo_fuerte:
        settings.modelo_fuerte = args.modelo_fuerte
        settings.escalar = True
    if args.modo:
        settings.modo = args.modo
    if args.auto:
        settings.modo = "auto"
    if args.sin_torneo:
        settings.torneo = False
    if args.sin_animacion:
        settings.animacion = False

    no_interactivo = bool(args.pedido or args.construir or args.plan or args.torneo or args.escribir
                          or args.evaluar is not None or args.comportamiento is not None)
    log = LOGS_DIR / f"{datetime.now():%Y%m%d}.log" if settings.log else None
    ui = UI(interactivo=not no_interactivo or sys.stdin.isatty(), log=log,
            detalle=0 if args.silencioso else settings.detalle)

    if args.instalar:
        return 0 if instalar_lanzador(ui) else 1

    api_key = obtener_clave_api(settings)
    if args.doctor:
        llm = LLMClient(api_key, settings) if api_key else None
        return 0 if diagnostico_sistema(ui, settings, llm, probar_modelo=bool(api_key)) else 1
    if not api_key:
        if not animar_intro():
            print(banner_dragon())
        variable = settings.variable_clave() or "OPENROUTER_API_KEY"
        ui.error(f"Falta {variable}.")
        ui.tenue(f'  export {variable}="tu_key"      (agregalo a ~/.bashrc para no repetirlo)')
        ui.tenue("  python3 reaper_v8.py --doctor    revisa todo el entorno")
        return 1

    limpiar_sandboxes_viejos()
    if settings.plugins:
        cargar_plugins(ui=ui)
    try:
        if args.nuevo:
            plantilla, carpeta = args.nuevo
            destino = Path(carpeta).expanduser().resolve()
            creados = crear_desde_plantilla(plantilla, destino)
            ui.ok(f"Proyecto creado en {destino} ({len(creados)} archivos)")
            args.proyecto = str(destino)
        if args.proyecto:
            raiz = resolver_workspace(args.proyecto)
        else:
            guardado = cargar_estado().get("proyecto")
            raiz = Path(guardado) if guardado and Path(guardado).is_dir() else PROJECTS_DIR
        ws = Workspace(raiz)
    except (ErrorRuta, KeyError, FileExistsError, OSError) as e:
        ui.error(str(e) if not isinstance(e, KeyError) else f"No existe la plantilla {e}")
        return 1

    llm = LLMClient(api_key, settings)
    llm.on_evento = lambda texto: ui.tenue(f"  ↻ {texto}")
    app = App(settings, llm, ui, ws)
    if args.proyecto:
        guardar_estado(proyecto=str(ws.raiz))

    inicio = time.monotonic()
    try:
        if args.evaluar is not None:
            return 0 if correr_evaluacion(llm, settings, ui, cantidad=args.evaluar or None) else 2
        if args.comportamiento is not None:
            return 0 if correr_comportamiento(llm, settings, ui, ids=args.comportamiento) else 2
        if args.construir:
            ok = app.construir(args.construir, confirmar=not args.auto)
            if time.monotonic() - inicio > 120:
                notificar("REAPER", f"Build {'verificada ✓' if ok else 'fallida ✗'}: {args.construir[:80]}")
            return 0 if ok else 2
        if args.torneo:
            app.cmd_torneo(args.torneo)
            return 0
        if args.escribir:
            app.cmd_escribir(" ".join(args.escribir))
            return 0
        if args.plan:
            app.cmd_plan(args.plan)
            return 0
        if args.pedido:
            return 0 if app.turno(args.pedido) else 2
        return app.repl(animar=settings.animacion)
    except (KeyboardInterrupt, Cancelado):
        CANCELAR.set()
        ui.aviso("\n⏹ Interrumpido.")
        return 130
    except LLMError as e:
        ui.error(f"Modelo: {e}")
        return 1


if __name__ == "__main__":
    sys.exit(main())
